const svg=$('#pigeon-svg'), out=$('#pigeon-out');
const nSl=$('#pigeon-n'), nL=$('#pigeon-n-lbl'), recolor=$('#pigeon-recolor'), c5btn=$('#pigeon-c5');
const W=640,H=360, cx=W/2, cy=H/2-6, R=132;
const RED='var(--pink)', BLUE='var(--blue)';
let n=+nSl.value, col={}; // col['i-j'] = 0 red / 1 blue
function key(i,j){ return i<j? i+'-'+j : j+'-'+i; }
function positions(){ const p=[]; for(let i=0;i<n;i++){ const a=-Math.PI/2 + 2*Math.PI*i/n; p.push([cx+R*Math.cos(a), cy+R*Math.sin(a)]); } return p; }
function randomize(){ col={}; for(let i=0;i<n;i++) for(let j=i+1;j<n;j++) col[key(i,j)] = Math.random()<0.5?0:1; }
function pentagon(){ n=5; nSl.value='5'; col={}; for(let i=0;i<5;i++) for(let j=i+1;j<5;j++){ const d=(j-i+5)%5; col[key(i,j)] = (d===1||d===4)?0:1; } } // rim red, diagonals blue
function findMono(c){ // first monochromatic triangle in color c, else null
  for(let i=0;i<n;i++) for(let j=i+1;j<n;j++) for(let k=j+1;k<n;k++)
    if(col[key(i,j)]===c && col[key(i,k)]===c && col[key(j,k)]===c) return [i,j,k];
  return null;
}
function render(){
  nL.textContent='n = '+n;
  const p=positions();
  svg.innerHTML='';
  const triR=findMono(0), triB=findMono(1);
  const hi=new Set();
  function mark(t){ if(t){ hi.add(key(t[0],t[1])); hi.add(key(t[0],t[2])); hi.add(key(t[1],t[2])); } }
  mark(triR); mark(triB);
  for(let i=0;i<n;i++) for(let j=i+1;j<n;j++){ const k=key(i,j); const c=col[k];
    const hit=hi.has(k);
    svg.appendChild(SVG('line',{x1:p[i][0],y1:p[i][1],x2:p[j][0],y2:p[j][1],
      stroke: c===0?RED:BLUE, 'stroke-width': hit?5:2, opacity: hit?1:0.55})); }
  for(let i=0;i<n;i++) drawNode(svg,p[i][0],p[i][1], i+1, {r:15, fill:'var(--panel2)', stroke:'var(--violet)'});
  let msg;
  if(triR && triB) msg='red triangle on {'+triR.map(x=>x+1).join(',')+'} AND blue triangle on {'+triB.map(x=>x+1).join(',')+'}';
  else if(triR) msg='monochromatic RED triangle on vertices {'+triR.map(x=>x+1).join(',')+'}';
  else if(triB) msg='monochromatic BLUE triangle on vertices {'+triB.map(x=>x+1).join(',')+'}';
  else msg='NO monochromatic triangle — a valid escape coloring';
  out.textContent =
    'n = '+n+'   edges 2-colored: '+(n*(n-1)/2)+'   (highlighted edges form a forced triangle)\n'+
    (n===6 ? 'K6: pigeonhole guarantees a monochromatic triangle in EVERY coloring (R(3,3) ≤ 6)\n'
           : 'K5: the pentagon coloring escapes — proving R(3,3) > 5\n')+
    'result: '+msg;
}
nSl.addEventListener('input',()=>{ n=+nSl.value; randomize(); render(); });
recolor.addEventListener('click',()=>{ randomize(); render(); });
c5btn.addEventListener('click',()=>{ pentagon(); render(); });
randomize(); render();

const svg=$('#finite-svg'), out=$('#finite-out');
const sSl=$('#finite-s'), sL=$('#finite-s-lbl'), tSl=$('#finite-t'), tL=$('#finite-t-lbl');
const W=640,H=300;
// memoized recurrence bound: R(2,t)=t, R(s,2)=s, else R(s-1,t)+R(s,t-1)
const memo={};
function recBound(s,t){
  if(s===2) return t; if(t===2) return s;
  const k=s+'-'+t; if(memo[k]!==undefined) return memo[k];
  return memo[k]=recBound(s-1,t)+recBound(s,t-1);
}
function binom(a,b){ if(b<0||b>a) return 0; let r=1; for(let i=0;i<b;i++) r=r*(a-i)/(i+1); return Math.round(r); }
// small table of known exact (or interval) values, keyed s<=t
const known={ '2-2':'2','3-3':'6','3-4':'9','3-5':'14','3-6':'18','3-7':'23','4-4':'18','4-5':'25','4-6':'36–40 (open)','5-5':'43–48 (open)','6-6':'102–161 (open)','7-7':'205–497 (open)' };
function lookup(s,t){ const a=Math.min(s,t), b=Math.max(s,t); return known[a+'-'+b]; }
function bar(x,y,w,h,fill,lab){ svg.appendChild(SVG('rect',{x,y,width:w,height:h,fill,rx:4,opacity:0.9})); const tx=SVG('text',{x:x+w+8,y:y+h*0.5+4,'font-size':13,fill:'var(--ink)'}); tx.textContent=lab; svg.appendChild(tx); }
function render(){
  let s=+sSl.value, t=+tSl.value; sL.textContent='s = '+s; tL.textContent='t = '+t;
  svg.innerHTML='';
  const rec=recBound(s,t), bin=binom(s+t-2,s-1);
  const exact=lookup(s,t);
  const maxV=Math.max(rec,bin, exact && /^[0-9]+$/.test(exact)?+exact:0, 1);
  const x0=140, fullW=380;
  const sc=v=> fullW * v / maxV;
  bar(x0, 60, sc(rec), 30, 'var(--violet)', 'recurrence ≤ '+rec);
  bar(x0, 110, sc(bin), 30, 'var(--cyan)', 'binomial C('+(s+t-2)+','+(s-1)+') = '+bin);
  const exTxt = exact ? ('R('+s+','+t+') = '+exact) : 'R('+s+','+t+') — not catalogued here';
  if(exact && /^[0-9]+$/.test(exact)) bar(x0, 160, sc(+exact), 30, 'var(--yellow)', exTxt);
  else { const tx=SVG('text',{x:x0,y:178,'font-size':13,fill:'var(--mute)'}); tx.textContent=exTxt; svg.appendChild(tx); }
  const cap=SVG('text',{x:x0,y:40,'font-size':13,fill:'var(--mute)'}); cap.textContent='upper bounds vs the known exact value'; svg.appendChild(cap);
  out.textContent =
    'R('+s+','+t+'):  recurrence bound R(s-1,t)+R(s,t-1) = '+rec+'\n'+
    '          binomial bound C(s+t-2, s-1) = C('+(s+t-2)+','+(s-1)+') = '+bin+'\n'+
    '          known exact value: '+(exact||'unknown / not listed')+'\n'+
    'the recurrence proves finiteness; exact values are scarce and stop being known around the diagonal R(5,5).';
}
sSl.addEventListener('input',render); tSl.addEventListener('input',render);
render();

const svg=$('#bounds-svg'), out=$('#bounds-out');
const sSl=$('#bounds-s'), sL=$('#bounds-s-lbl');
const W=640,H=340;
const x0=70, y0=H-50, plotW=W-150, plotH=H-90;
const sMin=3, sMax=12;
function lower(s){ return Math.pow(2, s/2); }
function upper(s){ return Math.pow(4, s); }
// known diagonal values (midpoint for open intervals)
const known={ 3:6, 4:18 };
const interval={ 5:[43,48], 6:[102,161] };
function render(){
  const sCur=+sSl.value; sL.textContent='s = '+sCur;
  svg.innerHTML='';
  const logMax=Math.log10(upper(sMax))*1.05;
  const sx=s=> x0 + plotW*(s-sMin)/(sMax-sMin);
  const ly=v=> y0 - plotH*Math.log10(Math.max(v,1))/logMax;
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0+plotW,y2:y0,stroke:'var(--line)','stroke-width':1.4}));
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0,y2:y0-plotH,stroke:'var(--line)','stroke-width':1.4}));
  for(let e=0;e<=7;e++){ const yy=ly(Math.pow(10,e)); if(yy<y0-plotH-2) break; svg.appendChild(SVG('line',{x1:x0,y1:yy,x2:x0+plotW,y2:yy,stroke:'var(--line)','stroke-width':0.6,opacity:0.4})); const tt=SVG('text',{x:x0-8,y:yy+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); tt.textContent='10^'+e; svg.appendChild(tt); }
  function curve(fn,color){ let d=''; for(let s=sMin;s<=sMax;s+=0.25){ d+=(d?'L':'M')+sx(s)+' '+ly(fn(s)); } svg.appendChild(SVG('path',{d,fill:'none',stroke:color,'stroke-width':2.2})); }
  curve(upper,'var(--pink)');
  curve(lower,'var(--cyan)');
  // labels
  const lu=SVG('text',{x:sx(sMax)+6,y:ly(upper(sMax))+4,'font-size':12,fill:'var(--pink)'}); lu.textContent='4^s'; svg.appendChild(lu);
  const ll=SVG('text',{x:sx(sMax)+6,y:ly(lower(sMax))+4,'font-size':12,fill:'var(--cyan)'}); ll.textContent='2^(s/2)'; svg.appendChild(ll);
  // x ticks
  for(let s=sMin;s<=sMax;s++){ const tt=SVG('text',{x:sx(s),y:y0+18,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); tt.textContent=s; svg.appendChild(tt); }
  // known points
  for(const s in known){ svg.appendChild(SVG('circle',{cx:sx(+s),cy:ly(known[s]),r:5,fill:'var(--yellow)',stroke:'var(--ink)'})); }
  for(const s in interval){ const [lo,hi]=interval[s]; svg.appendChild(SVG('line',{x1:sx(+s),y1:ly(lo),x2:sx(+s),y2:ly(hi),stroke:'var(--yellow)','stroke-width':3})); }
  // current-s vertical guide
  svg.appendChild(SVG('line',{x1:sx(sCur),y1:y0,x2:sx(sCur),y2:y0-plotH,stroke:'var(--violet)','stroke-width':1,'stroke-dasharray':'4 4'}));
  const lo=lower(sCur), up=upper(sCur);
  const exact = known[sCur] ? String(known[sCur]) : (interval[sCur]? interval[sCur][0]+'–'+interval[sCur][1]+' (open)' : 'unknown');
  function fmt(x){ return x>=1e5 ? x.toExponential(2) : Math.round(x); }
  out.textContent =
    's = '+sCur+'\n'+
    'lower bound  2^(s/2) = '+fmt(lo)+'   <   R(s,s)   <   4^s = '+fmt(up)+'\n'+
    'known R('+sCur+','+sCur+'): '+exact+'\n'+
    'yellow dots/bars = catalogued values; they vanish past s = 6. closing the base of the exponential is open.';
}
sSl.addEventListener('input',render);
render();

const svg=$('#infinite-svg'), out=$('#infinite-out');
const nSl=$('#infinite-n'), nL=$('#infinite-n-lbl'), stepBtn=$('#infinite-step'), resetBtn=$('#infinite-reset');
const W=640,H=320; const RED='var(--pink)', BLUE='var(--blue)';
let n=+nSl.value, color=[], chosen=[], chosenCol=[], pool=[], cur=null, curCol=null, done=false;
function key(i,j){ return i<j? i+'-'+j : j+'-'+i; }
function newColoring(){ color={}; for(let i=0;i<n;i++) for(let j=i+1;j<n;j++) color[key(i,j)]=Math.random()<0.5?0:1; }
function reset(){ newColoring(); chosen=[]; chosenCol=[]; pool=[]; for(let i=0;i<n;i++) pool.push(i); cur=null; curCol=null; done=false; }
function step(){
  if(done) return;
  if(pool.length<=1){ done=true; return; }
  const v=pool[0]; const rest=pool.slice(1);
  let red=[], blue=[]; for(const w of rest){ (color[key(v,w)]===0?red:blue).push(w); }
  const majRed = red.length>=blue.length;
  cur=v; curCol=majRed?0:1;
  chosen.push(v); chosenCol.push(curCol);
  pool = majRed?red:blue;
}
function xpos(i){ const top=46; return [70 + (W-110)*i/(n-1||1), top + (i%2)*0]; }
function render(){
  nL.textContent='n = '+n;
  svg.innerHTML='';
  const rowY=70;
  const inChosen=new Set(chosen); const inPool=new Set(pool);
  // draw selected monochromatic edges among chosen-with-later (only those committed)
  for(let p=0;p<chosen.length;p++){ const v=chosen[p], c=chosenCol[p];
    for(let q=p+1;q<chosen.length;q++){ const w=chosen[q];
      const a=[70+(W-110)*v/(n-1||1), rowY], b=[70+(W-110)*w/(n-1||1), rowY];
      const mx=(a[0]+b[0])/2, my=rowY+30+18*(q-p);
      svg.appendChild(SVG('path',{d:'M'+a[0]+' '+a[1]+' Q '+mx+' '+my+' '+b[0]+' '+b[1],fill:'none',stroke:c===0?RED:BLUE,'stroke-width':2.4,opacity:0.9})); } }
  for(let i=0;i<n;i++){ const x=70+(W-110)*i/(n-1||1);
    let fill='var(--panel2)', stroke='var(--line)';
    if(inChosen.has(i)){ const idx=chosen.indexOf(i); stroke = chosenCol[idx]===0?RED:BLUE; fill='var(--panel)'; }
    else if(inPool.has(i)){ stroke='var(--violet)'; }
    else { fill='#0b0f16'; }
    drawNode(svg,x,rowY,i,{r:13,fill,stroke,fontSize:12}); }
  // legend in viewport coords
  const lg=SVG('text',{x:70,y:H-40,'font-size':12,fill:'var(--mute)'}); lg.textContent='outlined = pool remaining   colored = chosen (edge color to all later chosen)   dim = discarded'; svg.appendChild(lg);
  const colName=curCol===null?'—':(curCol===0?'red':'blue');
  out.textContent =
    'homogeneous set so far: {'+chosen.join(', ')+'}'+(chosen.length?'':' (press “step construction”)')+'\n'+
    'last vertex picked: '+(cur===null?'—':cur)+'   its majority color into the pool: '+colName+'\n'+
    'pool remaining: {'+pool.join(', ')+'}   '+(done?'(pool exhausted in this finite window — the real construction never stops)':'')+'\n'+
    'each chosen vertex joins ALL later chosen vertices in one color; an infinite repeat of one color gives the infinite monochromatic set.';
}
nSl.addEventListener('input',()=>{ n=+nSl.value; reset(); render(); });
stepBtn.addEventListener('click',()=>{ step(); render(); });
resetBtn.addEventListener('click',()=>{ reset(); render(); });
reset(); render();

const svg=$('#vdw-svg'), out=$('#vdw-out');
const nSl=$('#vdw-n'), nL=$('#vdw-n-lbl'), rSl=$('#vdw-r'), rL=$('#vdw-r-lbl'), kSl=$('#vdw-k'), kL=$('#vdw-k-lbl');
const rand=$('#vdw-rand'), parity=$('#vdw-parity');
const W=640,H=200;
const palette=['var(--pink)','var(--blue)','var(--green)','var(--yellow)'];
let n=+nSl.value, r=+rSl.value, k=+kSl.value, col=[];
function randomize(){ col=[]; for(let i=0;i<n;i++) col.push(Math.floor(Math.random()*r)); }
function blockPattern(){ col=[]; const blk=Math.max(1,Math.floor(2)); for(let i=0;i<n;i++) col.push(Math.floor(i/2)%r); } // RRBB.. style
function findAP(){ // first monochromatic k-term AP, smallest (a,d)
  for(let d=1; d*(k-1) < n; d++){
    for(let a=0; a + d*(k-1) < n; a++){
      const c=col[a]; let ok=true;
      for(let t=1;t<k;t++) if(col[a+d*t]!==c){ ok=false; break; }
      if(ok){ const idx=[]; for(let t=0;t<k;t++) idx.push(a+d*t); return {c,idx,d}; }
    }
  }
  return null;
}
function render(){
  n=+nSl.value; r=+rSl.value; k=+kSl.value;
  nL.textContent='n = '+n; rL.textContent='r = '+r; kL.textContent='k = '+k;
  if(col.length!==n) randomize();
  svg.innerHTML='';
  const ap=findAP();
  const hit=new Set(ap?ap.idx:[]);
  const pad=40, gap=(W-2*pad)/Math.max(n-1,1), boxW=Math.min(gap*0.78, 26), y=80;
  for(let i=0;i<n;i++){ const x=pad+i*gap;
    svg.appendChild(SVG('rect',{x:x-boxW/2,y,width:boxW,height:34,rx:5,fill:palette[col[i]%palette.length],
      stroke: hit.has(i)?'var(--ink)':'var(--line)','stroke-width': hit.has(i)?3:1,opacity: hit.has(i)?1:0.78}));
    const t=SVG('text',{x,y:y+22,'text-anchor':'middle','font-size':12,fill:'#0b0d10','font-weight':600}); t.textContent=(i+1); svg.appendChild(t);
  }
  if(ap){ // draw connecting bracket under the AP
    const xs=ap.idx.map(i=>pad+i*gap);
    svg.appendChild(SVG('path',{d:'M'+xs[0]+' '+(y+44)+' L'+xs[xs.length-1]+' '+(y+44),stroke:'var(--ink)','stroke-width':2}));
  }
  const colName=ap?(['red','blue','green','yellow'][ap.c]):'—';
  out.textContent =
    'colored {1..'+n+'} with '+r+' colors; searching for a monochromatic '+k+'-term AP\n'+
    (ap ? ('FOUND: '+colName+' AP at positions {'+ap.idx.map(i=>i+1).join(', ')+'}  (common difference d = '+ap.d+')')
        : 'no monochromatic '+k+'-AP in this window — try a longer interval (Van der Waerden guarantees one once n ≥ W(r,k))')+'\n'+
    'reference: W(2,3)=9, W(2,4)=35, W(3,3)=27 — existence is certain, but the thresholds explode.';
}
function refreshAndDraw(reColor){ if(reColor) randomize(); render(); }
nSl.addEventListener('input',()=>{ n=+nSl.value; randomize(); render(); });
rSl.addEventListener('input',()=>{ r=+rSl.value; randomize(); render(); });
kSl.addEventListener('input',()=>{ k=+kSl.value; render(); });
rand.addEventListener('click',()=>{ randomize(); render(); });
parity.addEventListener('click',()=>{ blockPattern(); render(); });
randomize(); render();

const svg=$('#hj-svg'), out=$('#hj-out');
const tSl=$('#hj-t'), tL=$('#hj-t-lbl'), wSl=$('#hj-which'), wL=$('#hj-which-lbl'), fSl=$('#hj-fixed'), fL=$('#hj-fixed-lbl');
const nextBtn=$('#hj-next');
const W=640,H=360;
let t=+tSl.value, which=+wSl.value, fixed=+fSl.value;
function lineCells(){ // returns array of [c1,c2] forming the combinatorial line
  const cells=[];
  const fx=Math.min(fixed,t);
  for(let v=1;v<=t;v++){
    if(which===3) cells.push([v,v]);
    else if(which===1) cells.push([v,fx]);
    else cells.push([fx,v]);
  }
  return cells;
}
function phi(c1,c2){ return (c1-1) + (c2-1)*t; } // base-t value of (c1,c2)
function render(){
  t=+tSl.value; which=+wSl.value; fixed=Math.min(+fSl.value,t);
  tL.textContent='t = '+t; fL.textContent='fixed = '+fixed;
  wL.textContent = which===3?'both coords wildcard' : which===1?'coord 1 wildcard' : 'coord 2 wildcard';
  svg.innerHTML='';
  const cells=lineCells();
  const inLine=new Set(cells.map(c=>c[0]+'-'+c[1]));
  // grid: c1 = column (x), c2 = row (y), origin bottom-left
  const pad=70, cell=Math.min((W-2*pad)/t, 64), gx=pad, gy=60;
  for(let c2=t;c2>=1;c2--) for(let c1=1;c1<=t;c1++){
    const x=gx+(c1-1)*cell, y=gy+(t-c2)*cell;
    const on=inLine.has(c1+'-'+c2);
    svg.appendChild(SVG('rect',{x,y,width:cell-8,height:cell-8,rx:6,
      fill: on?'var(--cyan)':'var(--panel2)', stroke:'var(--line)','stroke-width':1, opacity: on?0.95:0.7}));
    const lab=SVG('text',{x:x+(cell-8)/2,y:y+(cell-8)/2+5,'text-anchor':'middle','font-size':13,
      fill: on?'#0b0d10':'var(--ink)','font-weight': on?700:400}); lab.textContent=''+c1+c2; svg.appendChild(lab);
  }
  // projection: arithmetic progression of phi-values below the grid
  const vals=cells.map(c=>phi(c[0],c[1])).sort((a,b)=>a-b);
  const baseY=gy + t*cell + 36;
  const lab2=SVG('text',{x:gx,y:baseY-12,'font-size':12,fill:'var(--mute)'}); lab2.textContent='base-'+t+' values φ(c) form an arithmetic progression:'; svg.appendChild(lab2);
  const span=(W-2*pad), maxV=t*t;
  for(let i=0;i<vals.length;i++){ const x=gx + span*vals[i]/Math.max(maxV-1,1);
    svg.appendChild(SVG('circle',{cx:x,cy:baseY+16,r:11,fill:'var(--yellow)',stroke:'var(--ink)'}));
    const tx=SVG('text',{x,y:baseY+21,'text-anchor':'middle','font-size':11,fill:'#0b0d10','font-weight':600}); tx.textContent=vals[i]; svg.appendChild(tx);
    if(i>0){ const xp=gx + span*vals[i-1]/Math.max(maxV-1,1); svg.appendChild(SVG('line',{x1:xp+11,y1:baseY+16,x2:x-11,y2:baseY+16,stroke:'var(--line)','stroke-width':1.4})); }
  }
  const d = vals.length>1 ? vals[1]-vals[0] : 0;
  out.textContent =
    'cube [t]^2 with t = '+t+'    line = {'+cells.map(c=>''+c[0]+c[1]).join(', ')+'}\n'+
    'wildcard: '+(which===3?'both coordinates move together':(which===1?'coordinate 1 moves, coordinate 2 fixed at '+fixed:'coordinate 2 moves, coordinate 1 fixed at '+fixed))+'\n'+
    'projected φ-values: '+vals.join(', ')+'   →  arithmetic progression with common difference d = '+d+'\n'+
    'so a combinatorial line maps to a '+t+'-term AP: Hales–Jewett ⇒ Van der Waerden.';
}
nextBtn.addEventListener('click',()=>{ which = which%3 + 1; wSl.value=String(which); render(); });
tSl.addEventListener('input',render); wSl.addEventListener('input',render); fSl.addEventListener('input',render);
render();
